  (forall g c k,
     open_co_wrt_co_rec k (g_Var_f c) (closeC_co c k g) = subst_co_co c (g_Var_f c) g) /\
  (forall p c k,
     open_constraint_wrt_co_rec k (g_Var_f c) (closeC_constraint c k p) = subst_co_constraint c (g_Var_f c) p).
