  AnnDefEq (rename_ctx_sw p q G) D'
           (rename_co (sw p q) (sw p q) g)
           (rename_tm (sw p q) (sw p q) a)
           (rename_tm (sw p q) (sw p q) b).
Proof.
  intros p q.
  apply (AnnDefEq_mut (AnnP_sw p q) (AnnT_sw p q) (AnnI_sw p q)
                      (AnnD_sw p q) (AnnC_sw p q) (AnnS_sw p q)).
  ann_cases.
Qed.
